<?php
declare(strict_types=1);
require_once __DIR__.'/_common.php';
require_once APP_ROOT.'/app/Import/ConsolidatedReconciliation.php';
$config=adminConfig('admin');requireDashboardAccess('matches');$db=bmaDatabase($config);$actor=adminReviewActor($db,$config);
if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET'){http_response_code(405);header('Allow: GET');exit('Read-only reconciliation preview.');}
header('Cache-Control: private, no-store');
try{$directory=ConsolidatedInputs::directory();$input=ConsolidatedInputs::read($directory,Paths::servedRoots($config));$approvals=[];$file=realpath($directory.'/approvals.json');if($file!==false){Paths::assertPrivate($file,Paths::servedRoots($config));if(filesize($file)>1048576)throw new RuntimeException('APPROVALS_INVALID');$approvals=json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR);}$p=(new ConsolidatedReconciliation($db))->preview($actor,$input,$approvals);}
catch(Throwable){http_response_code(503);adminHead('Consolidated reconciliation');echo '<div class="alert alert-warning">The private reconciliation preview is unavailable. No database records were changed.</div>';adminFoot();exit;}
adminHead('Consolidated reconciliation');echo '<h1 class="h3">Consolidated association preview</h1><p>Read-only references to existing sources. CSV evidence does not confirm identities, parentage or membership. Production apply requires separate administrator authorization and a complete database backup.</p><div class="row g-3">';foreach($p['summary'] as $key=>$value)echo '<div class="col-6 col-lg-3"><div class="surface-card card p-3"><strong class="h4">'.e($value).'</strong><span>'.e(str_replace('_',' ',$key)).'</span></div></div>';echo '</div><h2 class="h5 mt-4">Before counts (unchanged by preview)</h2><pre>'.e(json_encode($p['before_counts'],JSON_PRETTY_PRINT)).'</pre><p>Approval digest: <code>'.e($p['digest']).'</code>. This page has no apply action.</p><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Group</th><th>Student identity</th><th>Outcome</th><th>Review codes</th></tr></thead><tbody>';
foreach($p['groups'] as $g){$person=$p['entities'][$g['student_key']]['person_id']??null;echo '<tr><td>'.e($g['group_id']).'</td><td>'.($person===null?'Unresolved / proposed':'<a href="/member.php?person='.e($person).'">Verified person profile</a>').'</td><td>'.e($g['ready']?'Validated source group':'Needs review').'</td><td>'.e(implode(', ',array_merge($g['issues'],$g['proposals']))).'</td></tr>';}echo '</tbody></table></div>';adminFoot();
